#!/bin/bash
# Build the harness around src/arch/armv7/fault.c and run it on an emulated Cortex-M7 (QEMU, board mps2-an500: it
# models the MPU, including its access rights - which Renode does not, so the guard of the stack can only be checked here).
#
# Needs arm-none-eabi-gcc and qemu-system-arm. Usage: tests/fault_mpu/run.sh [BUILD_DIR]
set -e

HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
BUILD="${1:-$ROOT/build/fault_mpu}"
mkdir -p "$BUILD"

# dmod-config.h is generated by the build of dmod: use the one of the firmware build (configure it first)
CONFIG_DIR="$(dirname "$(find "$ROOT/build" -name dmod-config.h -not -path '*/fault_mpu/*' | head -n 1)")"
CPU="-mcpu=cortex-m7 -mthumb -mfpu=fpv5-d16 -mfloat-abi=hard"
CFLAGS="$CPU -Os -g -ffreestanding -Wall -DDMOD_CURRENT_ALLOCATOR=\"harness\" \
        -I$ROOT/lib/dmod/inc -I$ROOT/lib/dmosi/include -I$CONFIG_DIR"

arm-none-eabi-gcc $CFLAGS -c "$ROOT/src/arch/armv7/fault.c" -o "$BUILD/fault.o"
arm-none-eabi-gcc $CFLAGS -c "$HERE/harness.c" -o "$BUILD/harness.o"
arm-none-eabi-gcc $CPU -nostdlib -T "$HERE/link.ld" "$BUILD/fault.o" "$BUILD/harness.o" -o "$BUILD/harness.elf" -lgcc

OUTPUT="$(timeout 30 qemu-system-arm -M mps2-an500 -cpu cortex-m7 -nographic \
          -semihosting-config enable=on,target=native -kernel "$BUILD/harness.elf" 2>&1)" || true
echo "$OUTPUT"

# Each phase has to end in the recovery entry, as a stack overflow (type 1)
if [ "$(echo "$OUTPUT" | grep -c 'RECOVERED in thread context')" -eq 2 ] \
   && [ "$(echo "$OUTPUT" | grep -c 'type=00000001')" -eq 2 ] \
   && echo "$OUTPUT" | grep -q 'ALL PHASES DONE' \
   && ! echo "$OUTPUT" | grep -q 'NOT FAULTED\|HALT'; then
    echo "✓ The stack guard and the fault handlers work"
else
    echo "✗ The stack guard or the fault handlers do not work"
    exit 1
fi
